/bin/bash -lc "node --input-type=module <<'NODE'
const base = 'http://localhost:3100'
for (const [label, path, expectedStatus, expectedText] of [
  ['generated post', '/blog/1', 200, 'By:'],
  ['on-demand post', '/blog/11', 200, 'By:'],
  ['missing post', '/blog/999', 404, '404 - Page Not Found'],
  ['not-found metadata', '/missing-route', 404, '<title>404 - Page Not Found</title>'],
]) {
  const response = await fetch(base + path)
  const html = await response.text()
  const ok = response.status === expectedStatus && html.includes(expectedText)
  console.log("'`${ok ? '"'PASS' : 'FAIL'} "'${label}: ${response.status}`)
  if (!ok) process.exitCode = 1
}
NODE'

